CREATE TABLE IF NOT EXISTS economic_consensus_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reconciliation_id uuid NOT NULL, profile_id uuid NOT NULL, conflict_type text NOT NULL, subject text NOT NULL, supporting_refs jsonb NOT NULL DEFAULT '[]'::jsonb, opposing_refs jsonb NOT NULL DEFAULT '[]'::jsonb, resolution_state text NOT NULL DEFAULT 'pending_review', explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now())